import { useEffect, useState } from "react";
import { useParams } from "react-router-dom"

const UpdateData = () => {

    let [datas, setData] = useState([])
    const {id} = useParams()

    const getdata = async () => {
        let url = "http://localhost:1111/main/" + id;
        try{
            await fetch(url)
            .then( res => res.json() )
            .then( info => {
                setData
            })

        }catch(error){
            console.log(" Data processing vailed..... ")
        }
    }

    useEffect( () => {
        getdata()
    }, [])

    const handle = () => {

    }

    const handlesubmit = () => {

    }

    return(
        <div className="container" >
            <div className="row mt-5" >
                <h2 className="text-center mb-4 text-danger fw-bold" >Update Value</h2>
                <div className="col-lg-4" ></div>
                <div className="col-lg-4" >
                    <form className="col-12" onSubmit={handlesubmit}>

                        <div className="row mt-3" >
                            <div className="col-4" >
                                Id 
                            </div>
                            <div className="col-8" >
                                <input type="text" className=" form-control " name="id" onChange={handle} placeholder="Enter Your Name" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-4" >
                                Room-Name 
                            </div>
                            <div className="col-8" >
                                <input type="email" className=" form-control " name="Room-Name" onChange={handle} placeholder="Enter Your email" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-4" >
                                Image url 
                            </div>
                            <div className="col-8" >
                                <input type="number" className=" form-control " name="Image" onChange={handle} placeholder="Enter Your Number" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                <button className="btn btn-primary" >Submit</button>   
                            </div>
                        </div>   

                    </form>
                </div>
                <div className="col-lg-4" ></div>
            </div>
        </div>
    )
}

export default UpdateData
